#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <climits>
using namespace std;

typedef long long ll;
const ll INF = 1e18;

// Dijkstra's algorithm to compute shortest distances from source
vector<ll> dijkstra(int n, const vector<vector<pair<int, int>>>& adj, int start) {
    vector<ll> dist(n + 1, INF);
    dist[start] = 0;
    priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> pq;
    pq.push({0, start});

    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        if (d > dist[u]) continue;
        for (auto [v, w] : adj[u]) {
            ll newDist = d + w;
            if (newDist < dist[v]) {
                dist[v] = newDist;
                pq.push({newDist, v});
            }
        }
    }
    return dist;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k;
    cin >> n >> m >> k;

    // Build adjacency list
    vector<vector<pair<int, int>>> adj(n + 1);
    for (int i = 0; i < m; i++) {
        int u, v, w;
        cin >> u >> v >> w;
        adj[u].push_back({v, w});
        adj[v].push_back({u, w});
    }

    // Compute shortest distances from both ends
    vector<ll> dist1 = dijkstra(n, adj, 1);
    vector<ll> distN = dijkstra(n, adj, n);

    // Prepare nodes sorted by dist1
    vector<pair<ll, ll>> nodes;
    for (int i = 1; i <= n; i++) {
        nodes.push_back({dist1[i], distN[i]});
    }
    sort(nodes.begin(), nodes.end());

    // Precompute prefix minimum of distN
    int sz = nodes.size();
    vector<ll> prefixMin(sz);
    prefixMin[0] = nodes[0].second;
    for (int i = 1; i < sz; i++) {
        prefixMin[i] = min(prefixMin[i-1], nodes[i].second);
    }

    // Process each day
    for (int day = 0; day < k; day++) {
        ll a, b;
        cin >> a >> b;

        // Binary search on the maximum time T
        ll lo = 0, hi = INF;
        while (lo < hi) {
            ll mid = lo + (hi - lo) / 2;
            bool possible = false;

            // Maximum allowed dist1 for this T
            ll maxDist1 = (a > 0) ? mid / a : INF;

            // Find first node with dist1 > maxDist1
            auto it = upper_bound(nodes.begin(), nodes.end(), make_pair(maxDist1, INF));
            int pos = it - nodes.begin();

            if (pos > 0) {
                // Maximum allowed dist2 for this T
                ll maxDist2 = (b > 0) ? mid / b : INF;
                // Check if minimum distN in prefix [0, pos-1] <= maxDist2
                if (prefixMin[pos-1] <= maxDist2) {
                    possible = true;
                }
            }

            if (possible) {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }

        // Output the minimal waiting time (which is lo)
        cout << lo << "\n";
    }

    return 0;
}
```

**Explanation:**

1. **Graph Representation & Shortest Paths**:
   - The road network is stored as an adjacency list `adj`, where each node has a list of `(neighbor, weight)` pairs.
   - Dijkstra's algorithm is run twice: from node 1 and from node n, giving `dist1` and `distN`.

2. **Preprocessing**:
   - All nodes are stored as pairs `(dist1[i], distN[i])` and sorted by `dist1`.
   - A `prefixMin` array is computed where `prefixMin[i]` is the minimum `distN` among the first `i+1` nodes (sorted by `dist1`).

3. **Binary Search Optimization**:
   - For each query `(a, b)`, we binary search on the maximum travel time `T`.
   - To check feasibility for a given `T`:
     - Compute `maxDist1 = T / a` (maximum allowed `dist1`).
     - Use `upper_bound` to find the first node with `dist1 > maxDist1` (position `pos`).
     - If `pos > 0`, compute `maxDist2 = T / b` and check if `prefixMin[pos-1] <= maxDist2`.
     - If true, a feasible meeting point exists where both travel times are ≤ `T`.
   - This replaces the linear scan with O(log n) lookup via binary search and prefix array.

4. **Edge Case Handling**:
   - Division by zero is prevented by checking `a > 0` and `b > 0`.
   - `INF` is set to `1e18` to accommodate maximum distances (10^6) × maximum speed (10^6) × maximum path length.
   - The algorithm correctly handles cases where the optimal meeting point is node 1 or n.

5. **Complexity**:
   - Dijkstra: O((n + m) log n) for each source.
   - Sorting and prefix array: O(n log n).
   - Each query: O(log n · log INF) due to binary search on `T` with O(log n) feasibility checks.
   - Overall: O((n + m) log n + k log n log INF), efficient for constraints up to 10^5.

The solution outputs the minimal waiting time for each day, which equals the minimal maximum travel time found via binary search.

