from typing import List, Optional, Tuple, Any
from dataclasses import dataclass
import enum

class ResultType(enum.Enum):
    SUCCESS = "success"
    FAILURE = "failure"

@dataclass
class StepResponse:
    result: ResultType

@dataclass
class CreditChargesPayment:
    txn_id: str
    open_balance: float
    linked_payment_amount: str = ""

class PaymentChargesTableAction:
    @staticmethod
    def full_credits_table_update(credits_table: List[CreditChargesPayment]) -> None:
        """Simulate the Redux action dispatch"""
        pass

class PaymentTableSelectors:
    @staticmethod
    def get_credits() -> List[CreditChargesPayment]:
        """Simulate Redux selector for getting credits"""
        return []

    @staticmethod
    def get_total_of_charges_table() -> float:
        """Simulate Redux selector for getting total charges"""
        return 0.0

def validate_and_process_credit(
    credit: CreditChargesPayment, 
    remaining_balance: float
) -> Tuple[Optional[CreditChargesPayment], float, bool]:
    """
    Validate and process a single credit with comprehensive error handling.

    Handles edge cases:
    - Invalid linked_payment_amount (non-numeric strings)
    - Invalid open_balance
    - Empty txn_id

    Returns:
        Tuple[Optional[CreditChargesPayment], float, bool]: 
        (updated_credit, new_remaining_balance, was_updated)
        Returns (None, remaining_balance, False) for invalid credits
    """
    # Validate txn_id
    if not isinstance(credit.txn_id, str) or not credit.txn_id.strip():
        return None, remaining_balance, False

    # Validate open_balance
    if not isinstance(credit.open_balance, (int, float)) or credit.open_balance < 0:
        return None, remaining_balance, False

    # Validate linked_payment_amount type
    if not isinstance(credit.linked_payment_amount, str):
        return None, remaining_balance, False

    # Skip if no linked payment amount to process
    linked_amount = credit.linked_payment_amount.strip()
    if not linked_amount:
        return credit, remaining_balance, False

    # Validate linked_payment_amount is numeric
    try:
        float(linked_amount)
    except (ValueError, TypeError):
        return credit, remaining_balance, False

    # Calculate new amount based on remaining balance
    if remaining_balance >= credit.open_balance:
        new_amount = str(credit.open_balance)
        new_remaining = remaining_balance - credit.open_balance
    elif remaining_balance > 0:
        new_amount = str(remaining_balance)
        new_remaining = 0
    else:
        new_amount = ""
        new_remaining = remaining_balance

    # Only update if amount changed
    if credit.linked_payment_amount == new_amount:
        return credit, new_remaining, False

    # Create updated credit
    updated_credit = CreditChargesPayment(
        txn_id=credit.txn_id,
        open_balance=credit.open_balance,
        linked_payment_amount=new_amount
    )

    return updated_credit, new_remaining, True

def validate_input_data(
    credit_table_lines: Any,
    total_charges: Any
) -> Tuple[bool, Optional[str], List[CreditChargesPayment]]:
    """
    Consolidated validation for all input data.

    Returns:
        Tuple[bool, Optional[str], List[CreditChargesPayment]]: 
        (is_valid, error_message, valid_credits)
    """
    # Validate credit_table_lines is a list
    if not isinstance(credit_table_lines, list):
        return False, f"credit_table_lines must be a list, got {type(credit_table_lines)}", []

    # Validate each item in the list
    valid_credits = []
    invalid_items = []

    for i, item in enumerate(credit_table_lines):
        if isinstance(item, CreditChargesPayment):
            valid_credits.append(item)
        else:
            invalid_items.append((i, type(item)))

    # Report invalid items if any
    if invalid_items:
        invalid_types = ", ".join(f"index {i}: {t.__name__}" for i, t in invalid_items[:3])
        if len(invalid_items) > 3:
            invalid_types += f" ... and {len(invalid_items) - 3} more"
        print(f"Warning: Found {len(invalid_items)} non-CreditChargesPayment items: {invalid_types}")

    # Validate total_charges
    if not isinstance(total_charges, (int, float)):
        return False, f"total_charges must be numeric, got {type(total_charges)}", valid_credits

    if total_charges < 0:
        return False, f"total_charges cannot be negative: {total_charges}", valid_credits

    return True, None, valid_credits

def outstanding_transactions_handler_strict() -> StepResponse:
    """
    Strict handler with consolidated error handling and comprehensive edge case coverage.

    Handles:
    1. credit_table_lines containing unexpected data types
    2. Invalid linked_payment_amount (non-numeric strings)
    3. All other data validation in a consolidated manner

    Returns:
        StepResponse: Result of the operation
    """
    try:
        # Get data
        credit_table_lines = PaymentTableSelectors.get_credits()
        total_charges = PaymentTableSelectors.get_total_of_charges_table()

        # Consolidated validation
        is_valid, error_msg, valid_credits = validate_input_data(credit_table_lines, total_charges)
        if not is_valid:
            print(f"Validation error: {error_msg}")
            return StepResponse(result=ResultType.FAILURE)

        # Early return for empty data
        if not valid_credits or total_charges <= 0:
            PaymentChargesTableAction.full_credits_table_update([])
            return StepResponse(result=ResultType.SUCCESS)

        # Process valid credits
        remaining_balance = float(total_charges)
        updated_credits = []
        has_updates = False

        for credit in valid_credits:
            result, remaining_balance, was_updated = validate_and_process_credit(
                credit, remaining_balance
            )

            if result is not None:
                updated_credits.append(result)
                if was_updated:
                    has_updates = True

        # Dispatch update if we have updates or filtered out invalid data
        if has_updates or len(valid_credits) < len(credit_table_lines):
            PaymentChargesTableAction.full_credits_table_update(updated_credits)

        return StepResponse(result=ResultType.SUCCESS)

    except Exception as e:
        print(f"Unexpected error in transaction handler: {e}")
        import traceback
        traceback.print_exc()
        return StepResponse(result=ResultType.FAILURE)

# Example usage with comprehensive edge cases
if __name__ == "__main__":
    class TestSelectors(PaymentTableSelectors):
        @staticmethod
        def get_credits() -> List[Any]:
            return [
                CreditChargesPayment(txn_id="1", open_balance=100.0, linked_payment_amount="50"),
                CreditChargesPayment(txn_id="2", open_balance=200.0, linked_payment_amount=""),
                CreditChargesPayment(txn_id="3", open_balance=150.0, linked_payment_amount="100"),
                None,
                "not_a_credit",
                {"txn_id": "4", "open_balance": 50.0},
                CreditChargesPayment(txn_id="5", open_balance=-10.0, linked_payment_amount="10"),
                CreditChargesPayment(txn_id="6", open_balance=50.0, linked_payment_amount="not_a_number")
            ]

        @staticmethod
        def get_total_of_charges_table() -> float:
            return 250.0

    PaymentTableSelectors = TestSelectors

    print("Testing strict handler with edge cases:")
    result = outstanding_transactions_handler_strict()
    print(f"Result: {result.result.value}")
