function [Cl_theory, Cp_theory, x_theory] = compute_analytical_results(alpha_deg, airfoil_name, n_panels)
    alpha_rad = deg2rad(alpha_deg);
    Cl_theory = 2*pi*alpha_rad; % Thin airfoil theory

    % Cp distribution
    theta = linspace(0,pi,n_panels);
    x_theory = 0.5*(1-cos(theta));
    Cp_theory = 1 - 4*sin(theta).^2.*(sin(alpha_rad)./sin(theta) + cos(alpha_rad)).^2;

    % Apply thickness correction for NACA 0012
    if strcmpi(airfoil_name,'NACA0012')
        Cp_theory = Cp_theory .* (1 - 0.12*(1-x_theory).^0.5);
    end
end

