```go
package main

import (
    "fmt"
    "math"
    "math/rand"
    "sort"
    "strings"
    "time"
)

// ============================================
// STEP 1: DATA STRUCTURES
// ============================================

// Individual represents one budget allocation solution
type Individual struct {
    Weights []float64 // Allocation percentages for each category
    Fitness float64   // Quality score (higher is better)
}

// BudgetOptimizer manages the genetic algorithm process
type BudgetOptimizer struct {
    Categories  []string
    MinWeights  []float64
    MaxWeights  []float64
    TotalBudget float64

    // Genetic algorithm parameters
    PopulationSize int
    MutationRate   float64
    CrossoverRate  float64
    Generations    int

    // Performance data
    ExpectedReturns []float64
    RiskFactors     []float64
}

// ============================================
// STEP 2: INITIALIZATION
// ============================================

func NewBudgetOptimizer(categories []string, minWeights, maxWeights []float64, totalBudget float64) *BudgetOptimizer {
    // Validate inputs
    if len(categories) != len(minWeights) || len(categories) != len(maxWeights) {
        panic("Input arrays must have equal length")
    }

    // Initialize performance data (would use real data in practice)
    expectedReturns := make([]float64, len(categories))
    riskFactors := make([]float64, len(categories))
    for i := range categories {
        expectedReturns[i] = 0.05 + rand.Float64()*0.25 // 5-30% returns
        riskFactors[i] = 0.02 + rand.Float64()*0.20    // 2-22% risk
    }

    return &BudgetOptimizer{
        Categories:      categories,
        MinWeights:      minWeights,
        MaxWeights:      maxWeights,
        TotalBudget:     totalBudget,
        PopulationSize:  100,
        MutationRate:    0.15,
        CrossoverRate:   0.85,
        Generations:     200,
        ExpectedReturns: expectedReturns,
        RiskFactors:     riskFactors,
    }
}

// ============================================
// STEP 3: SOLUTION GENERATION
// ============================================

func (bo *BudgetOptimizer) createIndividual() *Individual {
    weights := make([]float64, len(bo.Categories))
    for i := range weights {
        weights[i] = bo.MinWeights[i] + rand.Float64()*(bo.MaxWeights[i]-bo.MinWeights[i])
    }
    bo.normalizeWeights(weights)
    return &Individual{Weights: weights}
}

func (bo *BudgetOptimizer) normalizeWeights(weights []float64) {
    total := 0.0
    for _, w := range weights {
        total += w
    }
    if total > 0 {
        scale := bo.TotalBudget / total
        for i := range weights {
            weights[i] *= scale
            // Ensure bounds after scaling
            weights[i] = math.Max(bo.MinWeights[i], math.Min(bo.MaxWeights[i], weights[i]))
        }
    }
}

// ============================================
// STEP 4: FITNESS CALCULATION
// ============================================

func (bo *BudgetOptimizer) calculateFitness(ind *Individual) float64 {
    totalReturn := 0.0
    totalRisk := 0.0
    for i, w := range ind.Weights {
        totalReturn += w * bo.ExpectedReturns[i]
        totalRisk += w * bo.RiskFactors[i]
    }

    fitness := totalReturn - totalRisk

    // Add penalty for constraint violations
    penalty := 0.0
    for i, w := range ind.Weights {
        if w < bo.MinWeights[i] {
            penalty += 10 * (bo.MinWeights[i] - w)
        }
        if w > bo.MaxWeights[i] {
            penalty += 10 * (w - bo.MaxWeights[i])
        }
    }

    totalWeight := 0.0
    for _, w := range ind.Weights {
        totalWeight += w
    }
    if math.Abs(totalWeight-bo.TotalBudget) > 0.01 {
        penalty += 100 * math.Abs(totalWeight-bo.TotalBudget)
    }

    return fitness - penalty
}

// ============================================
// STEP 5: GENETIC OPERATIONS
// ============================================

func (bo *BudgetOptimizer) selectParents(population []*Individual) (*Individual, *Individual) {
    // Simple tournament selection
    parent1 := population[rand.Intn(len(population))]
    parent2 := population[rand.Intn(len(population))]
    if parent1.Fitness > parent2.Fitness {
        return parent1, parent2
    }
    return parent2, parent1
}

func (bo *BudgetOptimizer) crossover(parent1, parent2 *Individual) (*Individual, *Individual) {
    if rand.Float64() > bo.CrossoverRate {
        return parent1, parent2
    }

    child1 := &Individual{Weights: make([]float64, len(parent1.Weights))}
    child2 := &Individual{Weights: make([]float64, len(parent2.Weights))}

    alpha := rand.Float64()
    for i := range parent1.Weights {
        child1.Weights[i] = alpha*parent1.Weights[i] + (1-alpha)*parent2.Weights[i]
        child2.Weights[i] = (1-alpha)*parent1.Weights[i] + alpha*parent2.Weights[i]
    }

    bo.normalizeWeights(child1.Weights)
    bo.normalizeWeights(child2.Weights)

    return child1, child2
}

func (bo *BudgetOptimizer) mutate(ind *Individual) {
    for i := range ind.Weights {
        if rand.Float64() < bo.MutationRate {
            mutation := rand.NormFloat64() * 0.1 * (bo.MaxWeights[i]-bo.MinWeights[i])
            ind.Weights[i] += mutation
            ind.Weights[i] = math.Max(bo.MinWeights[i], math.Min(bo.MaxWeights[i], ind.Weights[i]))
        }
    }
    bo.normalizeWeights(ind.Weights)
}

// ============================================
// STEP 6: POPULATION MANAGEMENT
// ============================================

func (bo *BudgetOptimizer) createInitialPopulation() []*Individual {
    population := make([]*Individual, bo.PopulationSize)
    for i := range population {
        population[i] = bo.createIndividual()
        population[i].Fitness = bo.calculateFitness(population[i])
    }
    return population
}

func (bo *BudgetOptimizer) sortPopulation(population []*Individual) {
    sort.Slice(population, func(i, j int) bool {
        return population[i].Fitness > population[j].Fitness
    })
}

// ============================================
// STEP 7: MAIN ALGORITHM LOOP
// ============================================

func (bo *BudgetOptimizer) Run() *Individual {
    rand.Seed(time.Now().UnixNano())
    population := bo.createInitialPopulation()
    bo.sortPopulation(population)

    bestIndividual := population[0]

    for generation := 0; generation < bo.Generations; generation++ {
        newPopulation := make([]*Individual, 0, bo.PopulationSize)

        // Keep top 2 solutions (elitism)
        for i := 0; i < 2 && i < bo.PopulationSize; i++ {
            elite := &Individual{
                Weights: make([]float64, len(population[i].Weights)),
                Fitness: population[i].Fitness,
            }
            copy(elite.Weights, population[i].Weights)
            newPopulation = append(newPopulation, elite)
        }

        // Generate new solutions
        for len(newPopulation) < bo.PopulationSize {
            parent1, parent2 := bo.selectParents(population)
            child1, child2 := bo.crossover(parent1, parent2)
            bo.mutate(child1)
            bo.mutate(child2)
            child1.Fitness = bo.calculateFitness(child1)
            child2.Fitness = bo.calculateFitness(child2)
            newPopulation = append(newPopulation, child1, child2)
        }

        // Trim if needed
        if len(newPopulation) > bo.PopulationSize {
            newPopulation = newPopulation[:bo.PopulationSize]
        }

        bo.sortPopulation(newPopulation)
        population = newPopulation

        // Update best solution
        if population[0].Fitness > bestIndividual.Fitness {
            bestIndividual = &Individual{
                Weights: make([]float64, len(population[0].Weights)),
                Fitness: population[0].Fitness,
            }
            copy(bestIndividual.Weights, population[0].Weights)
        }

        if generation%50 == 0 {
            fmt.Printf("Generation %d: Best = %.4f\n", generation, population[0].Fitness)
        }
    }

    return bestIndividual
}

// ============================================
// STEP 8: RESULTS DISPLAY
// ============================================

func (bo *BudgetOptimizer) PrintResults(best *Individual) {
    fmt.Println("\n" + strings.Repeat("=", 60))
    fmt.Println("OPTIMAL BUDGET ALLOCATION")
    fmt.Println(strings.Repeat("=", 60))

    total := 0.0
    for i, category := range bo.Categories {
        allocation := best.Weights[i]
        total += allocation
        fmt.Printf("%-20s: %.3f (%.1f%%)\n", category, allocation, allocation*100)
    }

    fmt.Printf("\nTotal Allocation: %.3f (Target: %.3f)\n", total, bo.TotalBudget)

    expectedReturn := 0.0
    expectedRisk := 0.0
    for i, w := range best.Weights {
        expectedReturn += w * bo.ExpectedReturns[i]
        expectedRisk += w * bo.RiskFactors[i]
    }

    fmt.Printf("\nExpected Return: %.2f%%\n", expectedReturn*100)
    fmt.Printf("Expected Risk:   %.2f%%\n", expectedRisk*100)
    fmt.Printf("Return/Risk Ratio: %.2f\n", expectedReturn/expectedRisk)
}

// ============================================
// STEP 9: EXAMPLE USAGE
// ============================================

func main() {
    rand.Seed(time.Now().UnixNano())

    categories := []string{"R&D", "Marketing", "Operations", "HR", "IT"}
    minWeights := []float64{0.10, 0.05, 0.20, 0.03, 0.08}
    maxWeights := []float64{0.35, 0.25, 0.40, 0.15, 0.25}

    optimizer := NewBudgetOptimizer(categories, minWeights, maxWeights, 1.0)

    fmt.Println("Starting optimization...")
    best := optimizer.Run()

    optimizer.PrintResults(best)
}
